<?php
namespace App\Services;use App\Jobs\DeliverWebhookJob;use App\Models\{OperationalEvent,Organization,Webhook,WebhookDelivery};use Illuminate\Support\Facades\Log;use Illuminate\Support\Str;
final class WebhookEventRouter{private const MAP=['automation_execution_failed'=>'automation.failed','provisioning_session_failed'=>'provisioning.failed','provisioning_session_expired'=>'provisioning.expired','firmware_delivery_unavailable'=>'firmware.delivery_unavailable'];public function routeOperationalEvent(OperationalEvent $e):void{$type=self::MAP[$e->event_type]??null;if(!$type||$e->source==='webhook'||!$e->organization)return;$this->dispatch($e->organization,$type,['event_id'=>(string)$e->id,'severity'=>$e->severity,'title'=>$e->title,'message'=>$e->message,'device'=>$e->device_id?['id'=>(string)$e->device_id]:null],(string)Str::uuid());}public function dispatch(Organization $o,string $type,array $data,?string $uuid=null):array{$out=[];$uuid??=(string)Str::uuid();foreach(Webhook::where('organization_id',$o->id)->where('enabled',true)->whereNotNull('approved_revision_id')->with('approvedRevision')->get()as$w){$events=$w->approvedRevision?->snapshot['configuration']['event_types']??[];if(in_array($type,$events,true))$out[]=$this->createDelivery($w,$uuid,$type,$data);}return $out;}public function dispatchToWebhook(Webhook $w,string $type,array $data):WebhookDelivery{return $this->createDelivery($w,(string)Str::uuid(),$type,$data);}private function createDelivery(Webhook $w,string $uuid,string $type,array $data):WebhookDelivery{$d=WebhookDelivery::firstOrCreate(['webhook_id'=>$w->id,'event_uuid'=>$uuid],['webhook_revision_id'=>$w->approved_revision_id,'activation_submission_id'=>$w->approved_submission_id,'event_type'=>$type,'payload'=>$this->envelope($uuid,$type,$w->organization,$data),'status'=>'pending']);if($d->wasRecentlyCreated){try{DeliverWebhookJob::dispatch($d->id)->afterCommit();}catch(\Throwable $e){$d->update(['status'=>'failed','error_code'=>'queue_dispatch_failed','error_message'=>'Webhook delivery could not be queued.']);Log::warning('Webhook job dispatch failed.',['delivery_id'=>$d->id,'exception'=>get_class($e)]);}}return $d;}private function envelope(string $id,string $type,Organization $o,array $data):array{return ['id'=>$id,'type'=>$type,'occurred_at'=>now()->toISOString(),'organization'=>['id'=>(string)$o->id],'data'=>$data];}}